FROM (
    SELECT t1.product_code AS product_code, t2.name AS product_name, t1.valid_from AS valid_from, t1.valid_to AS valid_to, t1.price AS price
    FROM store_prices AS t1
    LEFT JOIN local_products AS t2 ON t1.product_code = t2.product_code
